import pandas as pd

def fill_missing(df, strategy='mean', fill_value=None):
    """按策略填充 DataFrame 中的缺失值，并返回新副本。"""
    result = df.copy()
    for column in result.columns:
        series = result[column]
        if strategy == 'mean' and pd.api.types.is_numeric_dtype(series):
            result[column] = series.fillna(series.mean())
        elif strategy == 'median' and pd.api.types.is_numeric_dtype(series):
            result[column] = series.fillna(series.median())
        elif strategy == 'mode':
            mode_value = series.mode().iloc[0] if not series.mode().empty else fill_value
            result[column] = series.fillna(mode_value)
        else:
            result[column] = series.fillna(fill_value)  # 固定值策略或兜底分支。
    return result

def min_max_normalize(values):
    """使用 Min-Max 方法将数值序列缩放到 [0, 1] 区间。"""
    if not values:
        return []
    min_value = min(values)
    max_value = max(values)
    span = max_value - min_value
    if span == 0:
        return [0.0 for _ in values]  # 所有值一致时返回全 0。
    return [(value - min_value) / span for value in values]

def correlation_matrix(df):
    """计算输入表格的皮尔森相关系数矩阵，并输出热力图数据。"""
    corr = df.corr(method='pearson')
    return {
        'labels': list(corr.columns),
        'matrix': corr.round(4).values.tolist(),  # 保留四位小数便于前端展示。
    }

from scipy.stats import shapiro

def normality_test(values, alpha=0.05):
    """使用 Shapiro-Wilk 检验判断样本是否可视为正态分布。"""
    statistic, p_value = shapiro(values)
    return {
        'statistic': round(statistic, 4),
        'p_value': round(p_value, 4),
        'is_normal': p_value >= alpha,  # p 值高于显著性水平时接受正态假设。
    }

from sklearn.cluster import KMeans

def kmeans_cluster(X, n_clusters=3, random_state=42):
    """执行 K-Means 聚类并返回簇标签、聚类中心与惯性指标。"""
    model = KMeans(n_clusters=n_clusters, random_state=random_state, n_init='auto')
    labels = model.fit_predict(X)
    return {
        'labels': labels.tolist(),
        'centers': model.cluster_centers_.tolist(),
        'inertia': float(model.inertia_),  # 惯性可用于肘部法则辅助选择 K。
    }

def dtw_distance(series_a, series_b):
    """计算两条时间序列的动态时间弯曲距离。"""
    n, m = len(series_a), len(series_b)
    dp = [[float('inf')] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            cost = abs(series_a[i - 1] - series_b[j - 1])
            dp[i][j] = cost + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])
    return dp[n][m]

from torch.utils.data import Dataset

class CustomDataset(Dataset):
    """PyTorch 自定义数据集模板，用于封装样本与标签。"""
    def __init__(self, samples, labels, transform=None):
        self.samples = samples
        self.labels = labels
        self.transform = transform

    def __len__(self):
        return len(self.samples)

    def __getitem__(self, index):
        sample = self.samples[index]
        if self.transform:
            sample = self.transform(sample)  # 按需执行数据增强。
        return sample, self.labels[index]

