import random

def random_sample(data, ratio, seed=42):
    """从输入数据集中按比例执行随机无放回采样。"""
    if not data:
        return []  # 数据为空时直接返回空列表。
    sample_size = max(1, int(len(data) * ratio))
    random.seed(seed)  # 固定随机种子，保证结果可复现。
    sample_size = min(sample_size, len(data))
    return random.sample(list(data), sample_size)

