import datetime

def format_timestamp(ts, fmt='%Y-%m-%d %H:%M:%S'):
    # 将时间戳转为本地时间字符串
    return datetime.datetime.fromtimestamp(ts).strftime(fmt)

# 使用示例：format_timestamp(1700000000)

def deduplicate(lst):
    # 使用字典保序去重
    seen = {}
    return [seen.setdefault(x, x) for x in lst if x not in seen]

# 使用示例：deduplicate([1, 2, 2, 3, 1, 4])

import numpy as np

def rms(signal):
    # 计算均方根：sqrt(mean(x^2))
    return np.sqrt(np.mean(np.square(signal)))

# 使用示例：rms(np.array([1.0, -2.0, 3.0, -1.5]))

import numpy as np

def moving_average(data, window):
    # 使用卷积实现滑动均值
    return np.convolve(data, np.ones(window)/window, mode='valid')

# 使用示例：moving_average([1,2,3,4,5,6], window=3)

def sort_dicts(data, key, reverse=False):
    # 按指定字段对字典列表排序
    return sorted(data, key=lambda x: x.get(key), reverse=reverse)

# 使用示例：
data = [{'name': '张三', 'age': 25}, {'name': '李四', 'age': 22}]
sort_dicts(data, 'age')

import math

def euclidean_distance(p1, p2):
    # 计算欧氏距离：sqrt(sum((x1-x2)^2))
    return math.sqrt(sum((a - b) ** 2 for a, b in zip(p1, p2)))

# 使用示例：euclidean_distance([1, 2, 3], [4, 6, 3])

