def select_high_correlations(df, threshold=0.8):
    corr = df.corr(method='pearson').abs()
    pairs = []
    columns = list(corr.columns)
    for i, left in enumerate(columns):
        for right in columns[i + 1:]:
            score = float(corr.loc[left, right])
            if score >= threshold:
                pairs.append((left, right, round(score, 4)))
    return pairs

import numpy as np

def lstm_forecast(series, look_back=24, predict_steps=6):
    # 此处保留模型封装接口，具体训练逻辑由框架实现。
    windows = [series[i:i + look_back] for i in range(len(series) - look_back)]
    return np.array(windows[-predict_steps:])

